-- Kaart: Pranburi naar Aleenta, uitstapjes terug naar hun oorspronkelijke dag
update kaart set route = (
  select jsonb_agg(case when e->>'naam' = 'Pranburi' then jsonb_set(jsonb_set(e, '{lat}', '12.42'), '{lon}', '99.99') else e end order by o)
    from jsonb_array_elements(route) with ordinality t(e, o)),
  tussenstops = (select jsonb_agg(case
      when e->>'dag' between '2027-02-05' and '2027-02-14' then jsonb_set(e, '{dag}', to_jsonb(to_char((e->>'dag')::date - 1, 'YYYY-MM-DD')))
      else e end order by o) from jsonb_array_elements(tussenstops) with ordinality t(e, o)),
  dagtrips = (select jsonb_agg(case
      when e->>'naam' = 'Similan-eilanden' then e || '{"dag":"2027-02-15","tekst":"Optie: dagtrip met de speedboot naar de Similan-eilanden. Of een rustdag."}'::jsonb
      when e->>'naam' = 'Lam Ru' then e || '{"dag":"2027-02-15","tekst":"Waterval in het nationale park Lam Ru, op korte afstand van Khao Lak."}'::jsonb
      when e->>'dag' between '2027-02-05' and '2027-02-15' then jsonb_set(e, '{dag}', to_jsonb(to_char((e->>'dag')::date - 1, 'YYYY-MM-DD')))
      else e end order by o) from jsonb_array_elements(dagtrips) with ordinality t(e, o))
  where id = 'kaart';
